const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=x=>Math.max(0,Number.isFinite(Number(x))?Number(x):0);
const nf=x=>new Intl.NumberFormat('vi-VN').format(n(x));
const percent=(a,b)=>b?new Intl.NumberFormat('vi-VN',{maximumFractionDigits:1}).format(a/b*100)+'%':'—';
export const chartColors={teal:'#167f91',navy:'#0b3156',mint:'#69b9ae',amber:'#b98027',gray:'#80949e',track:'#e5eff0'};
const legend=items=>`<ul class="cms-chart-legend">${items.map(x=>`<li><i style="--series:${x.color}"></i><span>${esc(x.label)}</span>${x.value===undefined?'':`<strong>${nf(x.value)}</strong>`}</li>`).join('')}</ul>`;
const empty=text=>`<div class="cms-chart-empty"><strong>0</strong><span>${esc(text)}</span></div>`;
function table(headers,rows){return `<details class="cms-chart-data"><summary>Xem số liệu</summary><div><table><thead><tr>${headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map((v,i)=>i===0?`<th scope="row">${esc(v)}</th>`:`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details>`;}
export function chartPanel(title,subtitle,body,{wide=false,note=''}={}){return `<section class="cms-chart-panel${wide?' cms-chart-wide':''}"><header><h3>${esc(title)}</h3><p>${esc(subtitle)}</p></header>${body}${note?`<p class="cms-chart-note">${esc(note)}</p>`:''}</section>`;}
export function miniRing(value,total,label){const v=n(value),t=n(total),ratio=t?Math.min(1,v/t):0;return `<span class="cms-mini-ring" title="${esc(label)}: ${nf(v)} / ${nf(t)} (${percent(v,t)})"><svg viewBox="0 0 64 64" role="img" aria-label="${esc(label)}: ${nf(v)}/${nf(t)}, ${percent(v,t)}"><circle cx="32" cy="32" r="25" fill="none" stroke="${chartColors.track}" stroke-width="6"/><circle cx="32" cy="32" r="25" fill="none" stroke="${chartColors.teal}" stroke-width="6" pathLength="100" stroke-dasharray="${ratio*100} 100" transform="rotate(-90 32 32)"/><text x="32" y="36" text-anchor="middle">${percent(v,t)}</text></svg></span>`;}
export function donut(items,{caption='mục',emptyText='Chưa có dữ liệu trong nhóm này.'}={}){const rows=items.map(x=>({...x,value:n(x.value)})),total=rows.reduce((a,x)=>a+x.value,0);let offset=0;
 const arcs=rows.filter(x=>x.value>0).map(x=>{const fraction=x.value/total*100,part=`<circle cx="80" cy="80" r="58" fill="none" stroke="${x.color}" stroke-width="18" pathLength="100" stroke-dasharray="${fraction} ${100-fraction}" stroke-dashoffset="${-offset}" transform="rotate(-90 80 80)" tabindex="0" role="img" aria-label="${esc(x.label)}: ${nf(x.value)}, ${percent(x.value,total)}"><title>${esc(x.label)}: ${nf(x.value)} (${percent(x.value,total)})</title></circle>`;offset+=fraction;return part;}).join('');
 return `<div class="cms-donut-layout">${total?`<svg class="cms-donut" viewBox="0 0 160 160" role="img" aria-label="${esc(caption)}: ${nf(total)}"><circle cx="80" cy="80" r="58" fill="none" stroke="${chartColors.track}" stroke-width="18"/>${arcs}<text x="80" y="79" text-anchor="middle" class="cms-donut-total">${nf(total)}</text><text x="80" y="99" text-anchor="middle" class="cms-donut-caption">${esc(caption)}</text></svg>`:empty(emptyText)}${legend(rows)}</div>${table(['Phân loại','Số lượng','Tỷ lệ'],rows.map(x=>[x.label,nf(x.value),percent(x.value,total)]))}`;
}
export function horizontalBars(rows,{unit='mục',color=chartColors.teal}={}){const max=Math.max(0,...rows.map(x=>n(x.value)));
 return `${max?`<div class="cms-hbars" role="list" aria-label="Số lượng theo nhóm (${esc(unit)})">${rows.map(x=>`<div class="cms-hbar" role="listitem"><div>${x.action?`<button type="button" ${x.action}>${esc(x.label)}</button>`:`<span>${esc(x.label)}</span>`}<strong>${nf(x.value)}</strong></div><div class="cms-bar-track"><span style="width:${n(x.value)/max*100}%;--series:${x.color||color}" tabindex="0" role="img" aria-label="${esc(x.label)}: ${nf(x.value)} ${esc(unit)}"><span class="cms-chart-tip">${esc(x.label)}: ${nf(x.value)} ${esc(unit)}</span></span></div></div>`).join('')}</div><p class="cms-axis-note">Độ dài thanh: số ${esc(unit)} · 0–${nf(max)}</p>`:empty('Chưa ghi nhận '+unit+' trong nhóm này.')}${table(['Phân loại','Số '+unit],rows.map(x=>[x.label,nf(x.value)]))}`;
}
export function stackedGroups(groups,series){const totals=groups.map(g=>series.reduce((a,s)=>a+n(g[s.key]),0)),max=Math.max(1,...totals);
 return `${legend(series)}<div class="cms-group-bars" role="list">${groups.map((g,i)=>`<div class="cms-group-row" role="listitem"><div><button type="button" data-ov="group" data-group="${esc(g.group)}" data-filter="all">${esc(g.label)}</button><strong>${nf(totals[i])}</strong></div><div class="cms-bar-track">${series.map(s=>`<span style="width:${n(g[s.key])/max*100}%;--series:${s.color}" ${n(g[s.key])?'tabindex="0"':''} role="img" aria-label="${esc(g.label)} · ${esc(s.label)}: ${nf(g[s.key])}"><span class="cms-chart-tip">${esc(s.label)}: ${nf(g[s.key])}</span></span>`).join('')}</div></div>`).join('')}</div><p class="cms-axis-note">Độ dài thanh: số nghĩa vụ · 0–${nf(max)}</p>${table(['Nhóm',...series.map(s=>s.label),'Tổng'],groups.map((g,i)=>[g.label,...series.map(s=>nf(g[s.key])),nf(totals[i])]))}`;
}
export function dailyColumns(rows,series,{unit='lượt',emptyText='Chưa có hoạt động trong khoảng ngày này.'}={}){if(!rows.length)return empty(emptyText);const totals=rows.map(r=>series.reduce((a,s)=>a+n(r[s.key]),0)),peak=Math.max(0,...totals),legendRows=series.map(s=>({...s,value:rows.reduce((a,r)=>a+n(r[s.key]),0)}));
 const step=Math.max(1,Math.ceil(peak/4)),max=step*4,W=620,H=230,L=42,R=14,T=12,B=42,plotW=W-L-R,plotH=H-T-B,slot=plotW/rows.length,bw=Math.min(28,slot*.62),displayDate=d=>d.slice(8,10)+'/'+d.slice(5,7);
 const grid=Array.from({length:5},(_,i)=>{const value=i*step,y=H-B-value/max*plotH;return `<g><line x1="${L}" y1="${y}" x2="${W-R}" y2="${y}" class="cms-gridline"/><text x="${L-8}" y="${y+4}" text-anchor="end">${nf(value)}</text></g>`;}).join('');
 const bars=rows.map((r,i)=>{let offset=0;const x=L+i*slot+(slot-bw)/2,parts=series.map(s=>{const value=n(r[s.key]),height=value/max*plotH,y=H-B-offset/max*plotH-height;offset+=value;return `<rect x="${x}" y="${y}" width="${bw}" height="${height}" fill="${s.color}"/>`;}).join(''),label=`${displayDate(r.date)}: `+series.map(s=>`${s.label} ${nf(r[s.key])}`).join(', ');return `<g tabindex="0" role="img" aria-label="${esc(label)}"><title>${esc(label)}</title>${parts}<rect x="${L+i*slot}" y="${T}" width="${slot}" height="${plotH}" fill="transparent" class="cms-column-target"/></g>`;}).join('');
 const ticks=rows.map((r,i)=>i===0||i===rows.length-1||i%Math.max(1,Math.ceil(rows.length/7))===0?`<text x="${L+i*slot+slot/2}" y="${H-B+19}" text-anchor="middle">${displayDate(r.date)}</text>`:'').join('');
 return `${legend(legendRows)}${peak?`<svg class="cms-columns" viewBox="0 0 ${W} ${H}" role="img" aria-label="Số ${esc(unit)} theo ngày, ${displayDate(rows[0].date)}–${displayDate(rows.at(-1).date)}"><text x="${L}" y="${H-2}">Ngày (giờ Việt Nam)</text>${grid}${bars}${ticks}</svg><p class="cms-axis-note">Trục dọc: số ${esc(unit)} · Trục ngang: ngày, giờ Việt Nam</p>`:empty(emptyText)}${table(['Ngày (Việt Nam)',...series.map(s=>s.label),'Tổng '+unit],rows.map((r,i)=>[r.date,...series.map(s=>nf(r[s.key])),nf(totals[i])]))}`;
}
export function renderAnalytics(o,tab='checklists',days=14){const c=chartColors,ob=o.obligations,ch=o.changes,al=o.alerts,feed=o.feedback||{},fi=o.feedbackInsights||{},gs=ob.groups.filter(g=>g.group!=='hungyen').map(g=>({...g,label:({tax:'Thuế',accounting:'Kế toán',labor:'Lao động',insurance:'Bảo hiểm',company:'Doanh nghiệp',commerce:'Thương mại',data:'Dữ liệu',fire:'PCCC',environment:'Môi trường',food:'Thực phẩm'})[g.group]||'Khác'}));
 const lifecycle=[['draft','Bản nháp',c.mint],['inReview','Chờ duyệt',c.navy],['published','Đã phát hành',c.teal],['retired','Ngừng phát hành',c.gray]].map(([key,label,color])=>({key,label,color}));
 const card=chartPanel,range=`${days} ngày gần nhất · giờ Việt Nam`;let panels='';
 if(tab==='checklists')panels=card('Nghĩa vụ theo nhóm','Số nghĩa vụ hiện tại · bấm tên nhóm để kiểm tra',stackedGroups(gs,lifecycle),{wide:true,note:'Một nghĩa vụ được tính một lần; đã phát hành được ưu tiên nếu đang có bản nháp mới.'})+card('Trạng thái nghĩa vụ','Ảnh chụp hiện tại · không cộng trùng phiên bản',donut(lifecycle.map(s=>({...s,value:gs.reduce((a,g)=>a+n(g[s.key]),0)})),{caption:'nghĩa vụ'}))+card('Cơ sở duyệt checklist','Các nghĩa vụ đang phát hành',donut([{label:'Chuyên gia duyệt',value:ob.reviewBasis?.expert,color:c.teal},{label:'Tự duyệt, chưa thẩm định',value:ob.reviewBasis?.auto,color:c.amber}],{caption:'đang phát hành'}))+card('Cách theo dõi thời hạn','Các nghĩa vụ đang phát hành',horizontalBars([{label:'Hạn định kỳ',value:ob.deadlineKinds?.periodic},{label:'Hạn theo mốc / ngày cố định',value:ob.deadlineKinds?.once},{label:'Kỳ rà soát, chưa có ngày hạn',value:ob.deadlineKinds?.review},{label:'Không có quy tắc tính hạn',value:ob.deadlineKinds?.none}],{unit:'nghĩa vụ'}),{note:'Không có quy tắc tính hạn không đồng nghĩa nghĩa vụ không có thời hạn pháp lý.'})+card('Hoạt động duyệt checklist',range,dailyColumns((ob.approvalsPerDay||[]).slice(-days),[{key:'expert',label:'Chuyên gia duyệt',color:c.teal},{key:'auto',label:'Tự duyệt',color:c.amber}]),{wide:true,note:'Đếm lượt duyệt trong lịch sử, có thể gồm nhiều phiên bản của cùng một nghĩa vụ.'});
 if(tab==='changes')panels=card('Trạng thái đề xuất thay đổi luật','Toàn bộ đề xuất đã lưu',donut([{label:'Chờ xử lý',value:ch.pending,color:c.amber},{label:'Đã duyệt',value:ch.approved,color:c.teal},{label:'Đã loại',value:ch.rejected,color:c.gray}],{caption:'đề xuất'}),{note:'Đã duyệt là trạng thái đề xuất; không phải số thông báo đã giao.'})+card('Công đoạn của đề xuất đang chờ','Chỉ các đề xuất chưa duyệt',horizontalBars([{label:'Chờ phân loại',value:ch.stages?.NEW},{label:'Đang cập nhật nghĩa vụ',value:ch.stages?.OBLIGATION_UPDATE},{label:'Cần nhập văn bản',value:ch.stages?.NEEDS_IMPORT}],{unit:'đề xuất'}))+card('Loại thay đổi đang chờ','Một đề xuất thuộc một loại phát hiện',horizontalBars(Object.entries(ch.byKind||{}).map(([key,value])=>({label:({NEW_DOCUMENT:'Văn bản mới',RELATION:'Quan hệ sửa đổi',METADATA:'Thông tin văn bản',TEXT:'Toàn văn',ATTACHMENT:'Tệp đính kèm',MANUAL:'Đề xuất thủ công',PARSER_CHANGE:'Thay đổi bộ phân tích'})[key]||key,value})),{unit:'đề xuất'}))+card('Đề xuất mới theo ngày',range,dailyColumns((ch.perDay||[]).slice(-days),[{key:'count',label:'Đề xuất mới',color:c.teal}],{unit:'đề xuất',emptyText:'Chưa có đề xuất mới trong khoảng ngày này.'}));
 if(tab==='feedback')panels=card('Trạng thái phản hồi doanh nghiệp','Toàn bộ phản hồi đã gửi',donut([{label:'Mới gửi',value:feed.OPEN,color:c.amber},{label:'Đang xử lý',value:feed.IN_REVIEW,color:c.navy},{label:'Đã xử lý',value:feed.RESOLVED,color:c.teal},{label:'Không cần điều chỉnh',value:feed.DECLINED,color:c.gray}],{caption:'phản hồi',emptyText:'Chưa có phản hồi doanh nghiệp.'}))+card('Nhóm vấn đề doanh nghiệp phản ánh','Toàn bộ phản hồi đã gửi',horizontalBars(Object.entries(fi.byCategory||{}).map(([key,value])=>({label:({NOT_RELEVANT:'Không phù hợp / không cần làm',UNCLEAR:'Khó hiểu',CONTENT:'Nội dung chưa đúng',DEADLINE:'Thời hạn chưa đúng',TECHNICAL:'Lỗi thao tác',OTHER:'Góp ý khác'})[key]||key,value})),{unit:'phản hồi'}))+card('Tiếp nhận và trả lời theo ngày',range,dailyColumns((fi.perDay||[]).slice(-days),[{key:'received',label:'Phản hồi mới',color:c.teal},{key:'replies',label:'Lượt trả lời từ LIMI',color:c.navy}],{emptyText:'Chưa có trao đổi trong khoảng ngày này.'}),{wide:true,note:'Một phản hồi có thể được trả lời nhiều lần; hai chuỗi này không phải tỷ lệ xử lý xong.'});
 if(tab==='delivery')panels=card('Thông báo đã đến doanh nghiệp','30 ngày gần nhất · không gồm nội dung đang giữ',donut([{label:'Thay đổi luật / xác minh phạm vi',value:al.alerts30,color:c.teal},{label:'Nhắc hạn',value:al.reminders30,color:c.navy}],{caption:'thông báo'}),{note:`${nf(al.held30)} thông báo đang giữ để kiểm tra chất lượng, không tính là đã hiển thị.`})+card('Thông báo theo ngày',range,dailyColumns((al.perDay||[]).slice(-days),[{key:'law',label:'Luật / xác minh phạm vi',color:c.teal},{key:'reminder',label:'Nhắc hạn',color:c.navy}],{unit:'thông báo',emptyText:'Chưa có thông báo được giao trong khoảng ngày này.'}))+card('Hàng đợi và lỗi cần xử lý','Số lượng hiện tại · các hàng đợi độc lập',horizontalBars([{label:'Thông báo đang chờ giao',value:al.deliveryPending},{label:'Thông báo giao lỗi',value:al.deliveryFailed,color:c.amber},{label:'Đánh giá tác động đang chờ',value:al.impactsPending},{label:'Đánh giá tác động bị lỗi',value:al.impactsFailed,color:c.amber}],{unit:'mục'}))+card('Trạng thái URL theo dõi','Ảnh chụp hiện tại · việc thu thập không được bật lại',donut([{label:'Đang bật',value:o.sources.watchEnabled,color:c.teal},{label:'Đang tạm dừng',value:Math.max(0,n(o.sources.watchTotal)-n(o.sources.watchEnabled)),color:c.gray}],{caption:'URL theo dõi'}),{note:`24 giờ qua: ${nf(o.sources.observations24h?.total)} lượt kiểm tra, ${nf(o.sources.observations24h?.failed)} lượt ghi nhận lỗi.`});
 return `<section class="cms-analytics" aria-label="Biểu đồ quản lí"><div class="section-heading"><div><h2>Số liệu bằng biểu đồ</h2><p>Cơ cấu hiện tại và hoạt động theo ngày từ dữ liệu đã lưu.</p></div><label class="cms-range">Biểu đồ theo ngày<select data-cms-range aria-label="Khoảng thời gian biểu đồ">${[7,14].map(d=>`<option value="${d}" ${days===d?'selected':''}>${d} ngày gần nhất</option>`).join('')}</select></label></div><div class="tab-bar cms-chart-tabs" role="tablist" aria-label="Nhóm biểu đồ">${[['checklists','Checklist'],['changes','Thay đổi luật'],['feedback','Phản hồi'],['delivery','Thông báo & nguồn']].map(([key,label])=>`<button type="button" role="tab" id="cms-chart-tab-${key}" aria-controls="cms-chart-panel" aria-selected="${tab===key}" class="${tab===key?'active':''}" data-ov="chart-tab" data-tab="${key}">${label}</button>`).join('')}</div><div id="cms-chart-panel" role="tabpanel" aria-labelledby="cms-chart-tab-${tab}" class="cms-chart-grid">${panels}</div></section>`;
}
